import * as THREE from 'three/webgpu';
import { texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load texture via cached context loader
  const textureUrl = config.imageUrl || '/prism-assets/chrome/ceramic-grain.map.png';
  const textureMap = ctx.textureLoader.load(textureUrl);

  // Calculate dimensions from atlas region (512×320 → 1.6:1 aspect ratio)
  const aspectRatio = 512 / 320;
  const height = 1.0;
  const width = aspectRatio;

  // Create plane geometry
  const geometry = new THREE.PlaneGeometry(width, height);

  // Create TSL-based material with texture node
  const colorNode = texture(textureMap);
  const material = new THREE.MeshBasicNodeMaterial({
    colorNode: colorNode,
    side: THREE.DoubleSide,
  });

  // Create mesh and add to group
  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Cleanup function
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
  };

  // Event handlers (static card, no interactions)
  group.userData.handlers = {};

  return group;
}
